using System.Globalization;
using EasyQuerySharp.Metadata;
using EasyQuerySharp.Rendering;
using EasyQuerySharp.SqlAst;

namespace EasyQuerySharp.Dialects;

/// <summary>
/// IBM Db2 LUW 方言（11.5 / 12.1）。标识符用双引号；分页 <c>OFFSET n ROWS FETCH NEXT m ROWS ONLY</c>（与 Java 的 sql-db2 一致）；
/// 自增列 <c>GENERATED BY DEFAULT AS IDENTITY</c>，插入后在同一连接上取 <c>IDENTITY_VAL_LOCAL()</c>；冲突处理写成 <c>MERGE … USING (VALUES …)</c>；
/// 行锁 <c>FOR UPDATE WITH RS</c>（读到的行一直锁到事务结束）。
/// 驱动（如 Net.IBM.Data.Db2）由用户通过 <see cref="System.Data.Common.DbDataSource"/> 传入：<c>o.UseDb2(dataSource)</c>。
/// </summary>
public class Db2Dialect : SqlDialect
{
    /// <summary>共享实例。</summary>
    public static Db2Dialect Instance { get; } = new();

    /// <inheritdoc />
    public override NullsOrder DefaultNullsOrder(bool descending) => descending ? NullsOrder.First : NullsOrder.Last;

    /// <inheritdoc />
    public override string Name => "db2";

    /// <summary>Db2 的 INSERT 没有 RETURNING：同一连接上紧接着取 <c>IDENTITY_VAL_LOCAL()</c>。</summary>
    public override string? LastInsertIdQuery => "SELECT IDENTITY_VAL_LOCAL() FROM SYSIBM.SYSDUMMY1";

    /// <summary>SET 的列不带表别名。</summary>
    public override bool QualifySetColumns => false;

    /// <inheritdoc />
    public override string RecursiveWith => "WITH ";

    /// <summary>递归 CTE 必须写列名清单（否则 SQL0343N）。</summary>
    public override bool RecursiveCteColumnList => true;

    /// <summary>递归 CTE 的递归部分不能有带 ON 的显式连接（SQL0345N）：子节点表写成逗号连接。</summary>
    public override bool RecursiveCteCommaJoin => true;

    /// <summary>
    /// 参数写成 <c>CAST(@p0 AS 类型)</c>：Db2 不给无类型的参数标记推断类型的地方很多（CASE 的结果、函数参数、带单位的时长、SELECT 列表，
    /// SQL0418N / SQL0440N），按值的 CLR 类型写明；没有对应类型的（null、byte[]、Guid 等）照常写 <c>@p0</c>。
    /// </summary>
    public override string ParameterPlaceholder(int index, SqlParameterValue parameter) =>
        ParameterType(parameter) is { } type ? $"CAST(@p{index} AS {type})" : "@p" + index;

    /// <summary>
    /// IBM 的驱动不认 Guid、DateOnly、TimeOnly（赋值时报 Specified cast is not valid）：Guid 按 CHAR(36) 列传文本，
    /// DateOnly 传当天零点的 DateTime，TimeOnly 传 TimeSpan。
    /// </summary>
    public override object? ParameterValue(SqlParameterValue parameter) => parameter.Value switch
    {
        Guid g => g.ToString(),
        DateOnly d => d.ToDateTime(TimeOnly.MinValue),
        TimeOnly t => t.ToTimeSpan(),
        var value => value,
    };

    private static string? ParameterType(SqlParameterValue parameter)
    {
        var type = Nullable.GetUnderlyingType(parameter.ClrType) ?? parameter.ClrType;
        if (type.IsEnum) type = Enum.GetUnderlyingType(type);
        return type switch
        {
            // 字符串按 UTF-8 字节数取够长的 VARCHAR，超过 VARCHAR 上限的写 CLOB
            _ when type == typeof(string) => ((parameter.Value as string)?.Length * 4) switch
            {
                null or <= 4000 => "VARCHAR(4000)",
                <= 32672 => "VARCHAR(32672)",
                _ => "CLOB(2G)",
            },
            _ when type == typeof(bool) => "BOOLEAN",
            _ when type == typeof(byte) || type == typeof(sbyte) || type == typeof(short) => "SMALLINT",
            _ when type == typeof(int) || type == typeof(ushort) => "INTEGER",
            _ when type == typeof(long) || type == typeof(uint) || type == typeof(ulong) => "BIGINT",
            // 小数位数跟着值走，整数部分留够位数
            _ when type == typeof(decimal) => $"DECIMAL(31,{(parameter.Value is decimal d ? d.Scale : 0).ToString(CultureInfo.InvariantCulture)})",
            _ when type == typeof(double) => "DOUBLE",
            _ when type == typeof(float) => "REAL",
            _ when type == typeof(DateTime) => "TIMESTAMP",
            _ when type == typeof(DateOnly) => "DATE",
            _ when type == typeof(TimeOnly) || type == typeof(TimeSpan) => "TIME",
            _ => null,
        };
    }

    /// <summary>
    /// 有跳过行数时写 <c>OFFSET n ROWS [FETCH NEXT m ROWS ONLY]</c>，只取前几行时写 <c>FETCH FIRST m ROWS ONLY</c>（与 Java 的 DB2QuerySQLExpression 一致）。
    /// 跳过行数而没有排序时，按分组键、再不然按第一个主键（没有主键时第一列）排序，分页才稳定。
    /// </summary>
    public override void WritePaging(SqlRenderer renderer, SelectQuery query)
    {
        if (query.Offset is not > 0)
        {
            if (query.Limit is { } first) renderer.Append(" FETCH FIRST ").Append(first.ToString(CultureInfo.InvariantCulture)).Append(" ROWS ONLY");
            return;
        }
        if (query.OrderBy.Count == 0 && DefaultPagingOrder(query) is { } order) renderer.Append(" ORDER BY ").WriteList(order, ",");
        renderer.Append(" OFFSET ").Append(query.Offset.Value.ToString(CultureInfo.InvariantCulture)).Append(" ROWS");
        if (query.Limit is { } limit) renderer.Append(" FETCH NEXT ").Append(limit.ToString(CultureInfo.InvariantCulture)).Append(" ROWS ONLY");
    }

    private static IReadOnlyList<SqlExpr>? DefaultPagingOrder(SelectQuery query) => query switch
    {
        { GroupBy.Count: > 0 } => query.GroupBy,
        { From: EntityTableSource { Entity.KeyColumns: [var key, ..] } table } => [table.Column(key)],
        { From: EntityTableSource { Entity.Columns: [var first, ..] } table } => [table.Column(first)],
        _ => null,
    };

    /// <summary>
    /// <c>FOR UPDATE WITH RS</c>：默认的 CS 隔离级别下，游标离开的行不再加锁，要用 RS 才锁到事务结束；
    /// 跳过被锁的行 <c>FOR UPDATE SKIP LOCKED DATA</c>；没有 NOWAIT（锁等待用 <c>SET CURRENT LOCK TIMEOUT</c> 控制）。
    /// Java 写的是 <c>FOR UPDATE</c>，它的冒烟用例只检查 <c>… FETCH NEXT 2 ROWS ONLY FOR UPDATE</c> 这一段。
    /// </summary>
    public override void WriteLock(SqlRenderer renderer, RowLock rowLock) => renderer.Append(rowLock switch
    {
        RowLock.ForUpdate => " FOR UPDATE WITH RS",
        RowLock.ForUpdateSkipLocked => " FOR UPDATE SKIP LOCKED DATA",
        RowLock.ForUpdateNoWait => throw new NotSupportedException("Db2 不支持 FOR UPDATE NOWAIT：锁等待时间用 SET CURRENT LOCK TIMEOUT 控制"),
        _ => throw new ArgumentOutOfRangeException(nameof(rowLock), rowLock, null),
    });

    /// <summary>带对一导航的更新写成按主键对上的 MERGE（Db2 的 UPDATE 没有 FROM / JOIN）。</summary>
    public override void WriteJoinedUpdate(SqlRenderer renderer, UpdateStatement update) => WriteJoinedUpdateAsMerge(renderer, update);

    /// <summary>带对一导航的删除写成 EXISTS 子查询（Db2 的 DELETE 没有 USING / JOIN）。</summary>
    public override void WriteJoinedDelete(SqlRenderer renderer, DeleteStatement statement) => WriteJoinedDeleteAsExists(renderer, statement);

    /// <inheritdoc />
    public override bool InsertConflictUsesMerge => true;

    /// <summary>
    /// <c>MERGE INTO "t" t1 USING (VALUES (?,?),…) t2 ("a","b") ON (t1."k" = t2."k") [WHEN MATCHED THEN UPDATE SET "c" = t2."c",…]
    /// WHEN NOT MATCHED THEN INSERT ("a","b") VALUES (t2."a",t2."b")</c>：Db2 的 SELECT 不能省 FROM、选择列表里不能有无类型的参数，来源写成 VALUES；
    /// 可以一次多行。Java 的 DB2InsertSQLExpression 写成 <c>USING (SELECT ? AS …)</c> 并以分号结尾，在 Db2 上执行不了。
    /// </summary>
    public override void WriteMerge(SqlRenderer renderer, InsertStatement insert)
    {
        var columns = insert.Columns.Select(c => QuoteIdentifier(c.Name)).ToList();
        renderer.Append("MERGE INTO ").WriteTableName(insert.Table).Append(" t1 USING (VALUES ");
        for (var row = 0; row < insert.Rows.Count; row++)
        {
            if (row > 0) renderer.Append(",");
            renderer.Append("(").WriteList(insert.Rows[row], ",").Append(")");
        }
        renderer.Append(") t2 (" + string.Join(",", columns) + ") ON (")
            .Append(string.Join(" AND ", MergeKeys(insert).Select(k => $"t1.{QuoteIdentifier(k)} = t2.{QuoteIdentifier(k)}"))).Append(")");
        if (insert.Conflict!.UpdateColumns is { Count: > 0 } updates)
            renderer.Append(" WHEN MATCHED THEN UPDATE SET ").Append(string.Join(",", updates.Select(c => $"{QuoteIdentifier(c.Name)} = t2.{QuoteIdentifier(c.Name)}")));
        renderer.Append(" WHEN NOT MATCHED THEN INSERT (" + string.Join(",", columns) + ") VALUES (" + string.Join(",", columns.Select(c => "t2." + c)) + ")");
    }

    /// <summary>值里含 % 或 _ 时转义后写 <c>LIKE ? ESCAPE '\'</c>，按字面匹配。</summary>
    public override void WriteLike(SqlRenderer renderer, LikeExpr predicate)
    {
        if (predicate.HasWildcardValue) WriteEscapedLike(renderer, predicate, " ESCAPE '\\'");
        else base.WriteLike(renderer, predicate);
    }

    /// <summary>带组内排序的字符串聚合：<c>LISTAGG(CAST(x AS VARCHAR(4000)), '分隔符') WITHIN GROUP (ORDER BY …)</c>。</summary>
    public override void WriteOrderedStringJoin(SqlRenderer renderer, OrderedStringJoinExpr join)
    {
        WriteListAgg(renderer, join.Value, join.Separator, join.Distinct);
        renderer.Append(" WITHIN GROUP (");
        WriteOrderBy(renderer, join.Orders);
        renderer.Append(")");
    }

    /// <summary>
    /// <c>F(文档, '$.a[0].b')</c>：逐级的 Get 合并成一条路径。Db2 的路径不能从数组根开始（对 JSON_QUERY 取出的数组再取下标是 SQL16410N），
    /// 不能像别的库那样逐级套函数。<paramref name="last"/> 是最后一级按键（JsonGet，写 <c>.键</c>）还是按下标（JsonGetIndex，写 <c>[下标]</c>）。
    /// </summary>
    private static FunctionWriter JsonPathCall(string function, string last) => (r, a) =>
    {
        var path = Step(last, a[1]);
        var document = a[0];
        while (document is FunctionExpr { Name: SqlFunctionNames.JsonGet or SqlFunctionNames.JsonGetIndex } get)
        {
            path = Step(get.Name, get.Arguments[1]) + path;
            document = get.Arguments[0];
        }
        r.Append(function + "(").Write(document).Append(", '$" + path + "')");

        static string Step(string name, SqlExpr segment) =>
            name == SqlFunctionNames.JsonGet ? "." + ((LiteralExpr)segment).Sql : "[" + ((LiteralExpr)segment).Sql + "]";
    };

    // LISTAGG 的分隔符必须是常量：字符串参数改写成字面量
    private static void WriteListAgg(SqlRenderer renderer, SqlExpr value, SqlExpr separator, bool distinct)
    {
        renderer.Append(distinct ? "LISTAGG(DISTINCT CAST(" : "LISTAGG(CAST(").Write(value).Append(" AS VARCHAR(4000)), ");
        if (separator is ParameterExpr { Value: string text }) renderer.Append("'" + text.Replace("'", "''") + "'");
        else renderer.Write(separator);
        renderer.Append(")");
    }

    /// <summary>Db2 的类型转换（Java 的 DB2CastSQLFunction 照搬了 SQL Server 的类型名，如 uniqueidentifier、nvarchar(max)，这里改成 Db2 的）。</summary>
    public override string CastTemplate(Type targetType) => targetType switch
    {
        _ when targetType == typeof(bool) => "(CAST({0} AS VARCHAR(10)) NOT IN ('0','false'))",
        _ when targetType == typeof(char) => "SUBSTRING(CAST({0} AS VARCHAR(4000)),1,1,CODEUNITS32)",
        _ when targetType == typeof(TimeOnly) || targetType == typeof(TimeSpan) => "CAST({0} AS TIME)",
        _ when targetType == typeof(DateOnly) => "CAST({0} AS DATE)",
        _ when targetType == typeof(DateTime) => "CAST({0} AS TIMESTAMP)",
        _ when targetType == typeof(decimal) => "CAST({0} AS DECIMAL(31,18))",
        _ when targetType == typeof(double) || targetType == typeof(float) => "CAST({0} AS DOUBLE)",
        _ when targetType == typeof(byte) || targetType == typeof(sbyte) || targetType == typeof(short) => "CAST({0} AS SMALLINT)",
        _ when targetType == typeof(int) || targetType == typeof(ushort) => "CAST({0} AS INTEGER)",
        _ when IsInteger(targetType) => "CAST({0} AS BIGINT)",
        _ when targetType == typeof(Guid) => "CAST({0} AS CHAR(36))",
        _ when targetType == typeof(string) => "CAST({0} AS VARCHAR(4000))",
        _ => throw new NotSupportedException($"{Name} 不支持转换到 {targetType.Name}"),
    };

    /// <summary><c>"列" 类型 NULL|NOT NULL[ DEFAULT 默认值]</c>：Db2 不认 <c>DEFAULT … NULL</c> 的顺序（SQL0104N）；自增列按通用写法。</summary>
    protected override string ColumnDefinition(EntityMetadata entity, ColumnMetadata column) =>
        column.IsGenerated
            ? base.ColumnDefinition(entity, column)
            : $"{QuoteIdentifier(column.Name)} {ColumnType(column)} {(IsNullable(column) ? "NULL" : "NOT NULL")}{DefaultClause(column)}";

    /// <summary>字符串列按字符计长 <c>VARCHAR(n CODEUNITS32)</c>（默认按字节，中文一个字占 3 个字节）；Db2 LUW 没有带时区的时间戳。</summary>
    protected override string ClrColumnType(Type type, ColumnMetadata column) => type switch
    {
        _ when type == typeof(string) => "VARCHAR(255 CODEUNITS32)",
        _ when type == typeof(double) => "DOUBLE",
        _ when type == typeof(DateTimeOffset) => throw new NotSupportedException($"{column} 是 DateTimeOffset：Db2 LUW 没有带时区的时间戳，请改用 DateTime 存 UTC"),
        _ => base.ClrColumnType(type, column),
    };

    /// <summary>改表名：<c>RENAME TABLE 旧表 TO "新表"</c>。</summary>
    internal override string RenameTableSql(EntityMetadata entity, string oldName) =>
        $"RENAME TABLE {QualifiedName(entity.Schema, oldName)} TO {QuoteIdentifier(entity.TableName)}";

    /// <summary>读 SYSCAT 目录（当前模式，同 TS 版）。</summary>
    internal override CatalogQueries CatalogQueries { get; } = new(
        "SELECT TABNAME AS \"table_name\", REMARKS AS \"comment\" FROM SYSCAT.TABLES WHERE TABSCHEMA = CURRENT SCHEMA AND TYPE = 'T' ORDER BY TABNAME",
        "SELECT c.TABNAME AS \"table_name\", c.COLNAME AS \"column_name\", LOWER(c.TYPENAME) || CASE "
        + "WHEN c.TYPENAME IN ('VARCHAR', 'CHARACTER') AND c.TYPESTRINGUNITS = 'CODEUNITS32' THEN '(' || c.STRINGUNITSLENGTH || ' codeunits32)' "
        + "WHEN c.TYPENAME IN ('VARCHAR', 'CHARACTER') THEN '(' || c.LENGTH || ')' "
        + "WHEN c.TYPENAME = 'DECIMAL' THEN '(' || c.LENGTH || ', ' || c.SCALE || ')' "
        + "WHEN c.TYPENAME = 'TIMESTAMP' THEN '(' || c.SCALE || ')' ELSE '' END AS \"column_type\", "
        + "CASE c.NULLS WHEN 'Y' THEN 1 ELSE 0 END AS \"is_nullable\", c.\"DEFAULT\" AS \"column_default\", c.REMARKS AS \"comment\", "
        + "CASE c.IDENTITY WHEN 'Y' THEN 1 ELSE 0 END AS \"is_generated\", CASE WHEN c.KEYSEQ IS NULL THEN 0 ELSE 1 END AS \"primary_key\" "
        + "FROM SYSCAT.COLUMNS c WHERE c.TABSCHEMA = CURRENT SCHEMA ORDER BY c.TABNAME, c.COLNO",
        "SELECT i.TABNAME AS \"table_name\", i.INDNAME AS \"index_name\", CASE i.UNIQUERULE WHEN 'D' THEN 0 ELSE 1 END AS \"is_unique\", ic.COLNAME AS \"column_name\" "
        + "FROM SYSCAT.INDEXES i JOIN SYSCAT.INDEXCOLUSE ic ON ic.INDSCHEMA = i.INDSCHEMA AND ic.INDNAME = i.INDNAME "
        + "WHERE i.TABSCHEMA = CURRENT SCHEMA AND i.UNIQUERULE <> 'P' AND i.INDNAME NOT LIKE 'SQL%' ORDER BY i.TABNAME, i.INDNAME, ic.COLSEQ",
        "SELECT r.TABNAME AS \"table_name\", r.CONSTNAME AS \"constraint_name\", k.COLNAME AS \"column_name\", "
        + "r.REFTABNAME AS \"referenced_table\", rk.COLNAME AS \"referenced_column\" FROM SYSCAT.REFERENCES r "
        + "JOIN SYSCAT.KEYCOLUSE k ON k.TABSCHEMA = r.TABSCHEMA AND k.CONSTNAME = r.CONSTNAME "
        + "JOIN SYSCAT.KEYCOLUSE rk ON rk.TABSCHEMA = r.REFTABSCHEMA AND rk.CONSTNAME = r.REFKEYNAME AND rk.COLSEQ = k.COLSEQ "
        + "WHERE r.TABSCHEMA = CURRENT SCHEMA ORDER BY r.TABNAME, r.CONSTNAME, k.COLSEQ");

    /// <inheritdoc />
    protected override void RegisterFunctions(IDictionary<string, FunctionWriter> f)
    {
        base.RegisterFunctions(f);
        f[SqlFunctionNames.NullSafeEquals] = Template("({0} IS NOT DISTINCT FROM {1})");
        f[SqlFunctionNames.InCsv] = Template("(LOCATE(',' || {0} || ',',',' || {1} || ',') > 0)");
        f[SqlFunctionNames.MaxColumns] = Call("GREATEST");
        f[SqlFunctionNames.MinColumns] = Call("LEAST");
        // Db2 的 CONCAT 只接受两个参数（Java 写成多参数的 CONCAT，在 Db2 上执行不了）
        f[SqlFunctionNames.Concat] = Infix(" || ");
        // 长度、截取、查找都按字符（CODEUNITS32），不写时按字节
        f[SqlFunctionNames.Length] = Template("CHARACTER_LENGTH({0},CODEUNITS32)");
        f[SqlFunctionNames.SubString] = (r, a) =>
        {
            r.Append("SUBSTRING(").WriteList(a, ",");
            r.Append(",CODEUNITS32)");
        };
        // C# 的 IndexOf 是 0 起点，翻译时再减 1
        f[SqlFunctionNames.IndexOf] = Template("LOCATE({1},{0},1,CODEUNITS32)");
        f[SqlFunctionNames.LogBase] = Template("(LN({0}) / LN({1}))");
        // Db2 的 ATAN2 是 (x, y)，与标准 SQL 的 (y, x) 相反
        f[SqlFunctionNames.Atan2] = Reordered("ATAN2", 1, 0);
        f[SqlFunctionNames.Random] = Template("RAND()");
        f[SqlFunctionNames.UtcNow] = Template("(CURRENT_TIMESTAMP - CURRENT_TIMEZONE)");
        f[SqlFunctionNames.StringJoin] = (r, a) => WriteListAgg(r, a[0], a[1], false);
        f[SqlFunctionNames.StringJoinDistinct] = (r, a) => WriteListAgg(r, a[0], a[1], true);
        f[SqlFunctionNames.JsonGet] = JsonPathCall("JSON_QUERY", SqlFunctionNames.JsonGet);
        f[SqlFunctionNames.JsonGetIndex] = JsonPathCall("JSON_QUERY", SqlFunctionNames.JsonGetIndex);
        f[SqlFunctionNames.JsonText] = JsonPathCall("JSON_VALUE", SqlFunctionNames.JsonGet);
        f[SqlFunctionNames.JsonTextIndex] = JsonPathCall("JSON_VALUE", SqlFunctionNames.JsonGetIndex);
        f[SqlFunctionNames.JsonContainsKey] = JsonPathCall("JSON_EXISTS", SqlFunctionNames.JsonGet);
        foreach (var (unit, format) in new[] { (DateTruncUnit.Year, "YYYY"), (DateTruncUnit.Quarter, "Q"), (DateTruncUnit.Month, "MM"), (DateTruncUnit.Week, "IW"), (DateTruncUnit.Day, "DD"), (DateTruncUnit.Hour, "HH"), (DateTruncUnit.Minute, "MI") })
            f[SqlFunctionNames.DateTrunc(unit)] = Template("TRUNC_TIMESTAMP({0},'" + format + "')");
        // TRUNC_TIMESTAMP 没有到秒的格式：转成不带小数秒的 TIMESTAMP(0)
        f[SqlFunctionNames.DateTrunc(DateTruncUnit.Second)] = Template("CAST({0} AS TIMESTAMP(0))");
        // VARCHAR_FORMAT 的格式里只能有格式符与分隔符（- / . , : 空格，SQL0171N）：其余文字单独拼接
        f[SqlFunctionNames.DateFormat] = SegmentedDateFormat("VARCHAR_FORMAT",
            ("yyyy", "YYYY"), ("yy", "YY"), ("MM", "MM"), ("dd", "DD"), ("HH", "HH24"), ("hh", "HH12"), ("mm", "MI"), ("ss", "SS"), ("fff", "FF3"));
        // 相差：按经过的秒数整除（与其余方言一样截断）；先转 BIGINT，避免天数乘秒数溢出
        const string seconds = "(CAST(DAYS({1}) - DAYS({0}) AS BIGINT) * 86400 + MIDNIGHT_SECONDS({1}) - MIDNIGHT_SECONDS({0}))";
        DateFunctions(f,
            // 带单位的时长（labeled duration）：x + (n) DAYS
            unit => unit == DateUnit.Millisecond ? "({0} + (({1}) * 1000) MICROSECONDS)" : "({0} + ({1}) " + unit.ToString().ToUpperInvariant() + "S)",
            part => part switch
            {
                DatePart.DayOfYear => "DAYOFYEAR({0})",
                DatePart.DayOfWeek => "(DAYOFWEEK({0})-1)",
                DatePart.IsoDayOfWeek => "DAYOFWEEK_ISO({0})",
                _ => part.ToString().ToUpperInvariant() + "({0})",
            },
            unit => unit switch
            {
                DateUnit.Second => seconds,
                DateUnit.Millisecond => "(" + seconds + " * 1000 + (MICROSECOND({1}) - MICROSECOND({0})) / 1000)",
                _ => "(" + seconds + " / " + (unit switch { DateUnit.Minute => 60, DateUnit.Hour => 3600, _ => 86400 }).ToString(CultureInfo.InvariantCulture) + ")",
            });
    }
}
